function bitCountsUpTo(n: number): number[] {
  const counts: number[] = [];
  for (let i = 0; i <= n; i++) {
    let x = i, c = 0;
    while (x !== 0) { x &= x - 1; c++; }
    counts.push(c);
  }
  return counts;
}

